// P-code semantics check for the IA-64 module. Reads test/emu/cases.txt (generated by
// test/emu/cases.py from assembler source), and for each case writes the code at ram:1000,
// sets registers and memory, emulates with Ghidra's EmulatorHelper until the PC reaches the end
// of the main code (subroutines may follow it), and compares registers and memory with values
// worked out by hand from the Itanium Architecture Software Developer's Manual.
// The emulator runs with DECOMPILE_MODE = 0, so br.call / br.ret use the register stack engine
// (backing store at ar.bsp, set to ram:c000 here); sp (r12) starts at ram:f000.
//
// Case file lines: case <name> / code <hex> / main <main-code length in bytes, optional> /
//   set <reg> <value> | set ram:<hexaddr>[/<n>] <value>   (n bytes, little-endian)
//   expect <reg> <value> | expect ram:<hexaddr>[/<n>] <value> / end
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;

public class IA64EmuTest extends GhidraScript {

	private static class Case {
		String name;
		byte[] code;
		int mainLen = -1;
		Map<String, BigInteger> set = new LinkedHashMap<>();
		Map<String, BigInteger> expect = new LinkedHashMap<>();
	}

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						break;
					case "code":
						c.code = new byte[f[1].length() / 2];
						for (int i = 0; i < c.code.length; i++) {
							c.code[i] = (byte) Integer.parseInt(f[1].substring(2 * i, 2 * i + 2), 16);
						}
						break;
					case "main":
						c.mainLen = Integer.decode(f[1]);
						break;
					case "set":
						c.set.put(f[1], parse(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], parse(f[2]));
						break;
					case "end":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private static BigInteger parse(String v) {
		boolean neg = v.startsWith("-");
		String t = neg ? v.substring(1) : v;
		BigInteger r = t.startsWith("0x") ? new BigInteger(t.substring(2), 16) : new BigInteger(t);
		return neg ? BigInteger.ONE.shiftLeft(64).subtract(r) : r;
	}

	private Address addr(String loc) {
		String[] p = loc.split("[:/]");
		return currentProgram.getAddressFactory().getAddressSpace(p[0]).getAddress(
			Long.parseLong(p[1], 16));
	}

	private int size(String loc) {
		String[] p = loc.split("/");
		return p.length > 1 ? Integer.parseInt(p[1]) : 1;
	}

	private String runCase(Case c) throws Exception {
		Address start = addr("ram:1000");
		int mainLen = c.mainLen >= 0 ? c.mainLen : c.code.length;
		Address end = start.add(mainLen);
		AddressSet body = new AddressSet(start, start.add(c.code.length + 16));
		clearListing(body);
		setBytes(start, c.code);
		final EmulatorHelper emu = new EmulatorHelper(currentProgram);
		boolean be = currentProgram.getLanguage().isBigEndian();
		try {
			emu.writeRegister("r12", 0xf000);
			emu.writeRegister("ar.bsp", 0xc000);
			emu.writeRegister("DECOMPILE_MODE", 0);
			for (Map.Entry<String, BigInteger> e : c.set.entrySet()) {
				if (e.getKey().contains(":")) {
					int n = size(e.getKey());
					byte[] b = new byte[n];
					for (int i = 0; i < n; i++) {
						b[be ? n - 1 - i : i] = e.getValue().shiftRight(8 * i).byteValue();
					}
					emu.writeMemory(addr(e.getKey()), b);
				}
				else {
					emu.writeRegister(e.getKey(), e.getValue());
				}
			}
			emu.writeRegister(emu.getPCRegister(), start.getOffset());
			int steps = 0;
			while (!emu.getExecutionAddress().equals(end)) {
				if (++steps > 5000) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, BigInteger> e : c.expect.entrySet()) {
				BigInteger got;
				String key = e.getKey();
				if (key.endsWith("@le") || key.endsWith("@be")) {
					if (key.endsWith(be ? "@le" : "@be")) {
						continue;
					}
					key = key.substring(0, key.length() - 3);
				}
				if (key.contains(":")) {
					int n = size(key);
					byte[] b = emu.readMemory(addr(key), n);
					got = BigInteger.ZERO;
					for (int i = n - 1; i >= 0; i--) {
						got = got.shiftLeft(8).or(BigInteger.valueOf(b[be ? n - 1 - i : i] & 0xff));
					}
				}
				else {
					got = emu.readRegister(key);
				}
				if (!got.equals(e.getValue())) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", key, got,
						e.getValue()));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		List<Case> cases = load(args[0]);
		PrintStream out = new PrintStream(args[1]);
		int pass = 0, fail = 0;
		for (Case c : cases) {
			String err = runCase(c);
			if (err == null) {
				pass++;
				out.println("PASS " + c.name);
			}
			else {
				fail++;
				out.println("FAIL " + c.name + ": " + err);
			}
		}
		out.printf("emulation (%s): %d passed, %d failed%n", currentProgram.getLanguageID(), pass, fail);
		out.close();
	}
}
